 const risk=form.locator(`[data-account="${a.id}"] [name=riskPercent]`);await risk.fill('1');await form.locator('button.primary').click();assert.equal(await page.locator('#goldApprove').count(),0);await risk.fill('.5');await form.locator('button.primary').click();await page.locator('#goldApprove:not([disabled])').waitFor();assert.equal((await api('/api/workbench/cards/'+card.id)).plan,null);checks.push('1%前端被拦截；110万/200万最新余额按0.5%显示5500/10000元风险预算，摘要未批准');
