 await page.reload();await page.locator('[data-view=metal]').click();await page.locator('#goldApprove:not([disabled])').waitFor();assert.equal(await page.locator('#goldFinalCheck').isChecked(),false);assert.equal(await page.locator('#goldChoiceForm [name=intradayAlgorithm]').inputValue(),'隔离演示：成交额÷成交量÷合约乘数，按交易日重置');assert.equal(await page.locator('#goldTermsForm [name=holdingUntil]').inputValue(),day+'T23:58');assert.equal((await api('/api/workbench/cards/'+card.id)).plan,null);checks.push('重载恢复算法、截止与待审定摘要，最终拍板不自动勾选');
 await page.locator('#goldFinalCheck').check();await page.locator('#goldApprove').click();await page.waitForFunction(()=>document.querySelector('#goldStatus')?.textContent.includes('上一版已拍板'));const saved=await api('/api/workbench/cards/'+card.id);assert.equal(saved.plan.payload.methodChoice.method,'intraday');assert.equal(saved.plan.payload.riskPercent,.5);assert.equal(saved.plan.payload.mainCycle,'small');assert.equal(saved.plan.risk.permission,false);checks.push('仅隔离模拟库完成最终拍板，保存第五法参数；未写正式账户或发交易指令');
 await page.locator('#analyzeGold').click();await page.locator('#goldChoiceForm').waitFor();await page.locator('[name=method][value=trend]').check();await page.locator('#goldChoiceForm [name=confirmed]').check();await page.locator('#goldChoiceForm button.primary').click();await page.locator('#goldTermsForm').waitFor();const history=await api('/api/workbench/cards/'+card.id+'/gold');assert.equal(history.find(x=>x.stage==='method').derived.stop,2110);await page.locator('#goldSizingSuggestionButton').click();assert.equal(await page.locator('#goldTermsForm [name=stop]').inputValue(),'2110');checks.push('第四法计算仍守前一根完成日K2110，接受建议后正确带入；原手工值不被静默覆盖');
